func Compute(lines []Line, discountBP, taxBP int64) int64 {
	var totalDiscounted int64
	var totalTaxableAmount int64

	for _, l := range lines {
		lineTotal := l.Price * l.Qty
		// Apply discount to each order: (lineTotal * (10000 - discountBP)) / 10000
		// Round to nearest cent: (numerator + 5000) / 10000
		discounted := (lineTotal*(10000-discountBP) + 5000) / 10000
		totalDiscounted += discounted
		if l.Taxable {
			totalTaxableAmount += discounted
		}
	}

	// tax the discounted taxable amount. tax rounded once.
	// tax = (totalTaxableAmount * taxBP) / 10000 rounded to nearest cent
	tax := (totalTaxableAmount*taxBP + 5000) / 10000

	return totalDiscounted + tax
}

