		totalDiscounted += discountedAmount
		if l.Taxable {
			taxableDiscountedSum += discountedAmount
		}
	}

	// Sum discounted line amounts and add tax rounded once.
	// Tax is calculated on the sum of discounted taxable amounts.
	tax := (taxableDiscountedSum*taxBP + 5000) / 10000
	return totalDiscounted + tax
}

